export {
  Slider,
  SliderLabel,
  SliderValue,
  SliderControl,
  SliderTrack,
  SliderIndicator,
  SliderThumb,
} from "./slider";

import { tv, type VariantProps } from "tailwind-variants";

const slider = tv({
  slots: {
    root: [
      "grid data-[orientation='horizontal']:max-w-full data-[orientation='vertical']:max-h-full",
      "data-[orientation='horizontal']:grid-cols-[1fr_auto]",
      "data-[orientation='vertical']:grid-rows-[auto_1fr]",
    ],
    label: [
      "text-sm font-medium text-foreground transition-opacity duration-150 ease-default select-none",
      "data-disabled:opacity-50",
      "data-[orientation='vertical']:self-baseline-last",
    ],
    value: [
      "text-end text-sm text-foreground tabular-nums transition-[color,opacity] duration-150 ease-default",
      "data-disabled:opacity-50",
      "data-invalid:text-destructive",
      "data-[orientation='horizontal']:self-center",
      "data-[orientation='vertical']:col-start-1 data-[orientation='vertical']:row-start-1",
    ],
    control: [
      "flex touch-none items-center transition-opacity duration-150 ease-default select-none",
      "data-disabled:opacity-50",
      "data-[orientation='horizontal']:col-span-2",
      "data-[orientation='vertical']:col-start-2 data-[orientation='vertical']:row-span-2 data-[orientation='vertical']:row-start-1",
    ],
    track: [
      "rounded-full bg-muted",
      "data-[orientation='horizontal']:h-1 data-[orientation='horizontal']:w-full",
      "data-[orientation='vertical']:h-full data-[orientation='vertical']:w-1",
    ],
    indicator: "rounded-[inherit] bg-primary select-none",
    thumb: [
      "rounded-full border border-primary bg-background shadow-xs transition-[border-color,box-shadow] duration-150 ease-default select-none",
      "has-focus-visible:ring-2 has-focus-visible:ring-ring",
      "data-invalid:border-destructive",
      "data-invalid:has-focus-visible:ring-destructive",
    ],
  },
  variants: {
    size: {
      lg: {
        control: [
          "data-[orientation='horizontal']:py-4.5",
          "data-[orientation='vertical']:px-4.5",
        ],
        thumb: "size-5",
      },
      md: {
        control: [
          "data-[orientation='horizontal']:py-4",
          "data-[orientation='vertical']:px-4",
        ],
        thumb: "size-4.5",
      },
      sm: {
        control: [
          "data-[orientation='horizontal']:py-3.5",
          "data-[orientation='vertical']:px-3.5",
        ],
        thumb: "size-4",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

type SliderVariantProps = VariantProps<typeof slider>;

export { slider };
export type { SliderVariantProps };

"use client";

import { useDirection } from "@base-ui/react";
import { Slider as BaseSlider } from "@base-ui/react/slider";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { slider, type SliderVariantProps } from "./slider.style";

type SliderContext = SliderVariantProps;

const SliderContext = createContext<SliderContext>({
  size: "md",
});

function useSlider() {
  return useContext(SliderContext);
}

function Slider({
  size,
  className,
  children,
  ...props
}: BaseSlider.Root.Props & SliderVariantProps) {
  const direction = useDirection();

  return (
    <SliderContext.Provider value={{ size }}>
      <BaseSlider.Root
        data-slot="slider"
        className={mergeSlotClassName(slider().root, className)}
        {...props}
        dir={direction}
      >
        {children}
      </BaseSlider.Root>
    </SliderContext.Provider>
  );
}

function SliderLabel({ className, ...props }: BaseSlider.Label.Props) {
  return (
    <BaseSlider.Label
      data-slot="slider-label"
      className={mergeSlotClassName(slider().label, className)}
      {...props}
    />
  );
}

function SliderValue({ className, ...props }: BaseSlider.Value.Props) {
  return (
    <BaseSlider.Value
      data-slot="slider-value"
      className={mergeSlotClassName(slider().value, className)}
      {...props}
    />
  );
}

function SliderControl({ className, ...props }: BaseSlider.Control.Props) {
  const { size } = useSlider();

  return (
    <BaseSlider.Control
      data-slot="slider-control"
      className={mergeSlotClassName(slider({ size }).control, className)}
      {...props}
    />
  );
}

function SliderTrack({ className, ...props }: BaseSlider.Track.Props) {
  return (
    <BaseSlider.Track
      data-slot="slider-track"
      className={mergeSlotClassName(slider().track, className)}
      {...props}
    />
  );
}

function SliderIndicator({ className, ...props }: BaseSlider.Indicator.Props) {
  return (
    <BaseSlider.Indicator
      data-slot="slider-indicator"
      className={mergeSlotClassName(slider().indicator, className)}
      {...props}
    />
  );
}

function SliderThumb({ className, ...props }: BaseSlider.Thumb.Props) {
  const { size } = useSlider();

  return (
    <BaseSlider.Thumb
      data-slot="slider-thumb"
      className={mergeSlotClassName(slider({ size }).thumb, className)}
      {...props}
    />
  );
}

export {
  Slider,
  SliderLabel,
  SliderValue,
  SliderControl,
  SliderTrack,
  SliderIndicator,
  SliderThumb,
};
